# Objects and bounding-box qualification
seen=set();comps=[]
for r in range(R):
 for c in range(C):
  if g[r][c] and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));co=[]
   for x,y in q:
    co.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<R and 0<=b<C and g[a][b] and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   comps.append(co)
qual=[]
for co in comps:
 r0=min(r for r,c in co);r1=max(r for r,c in co);c0=min(c for r,c in co);c1=max(c for r,c in co)
 cav={(r,c) for r,c in interior if r0<=r<=r1 and c0<=c<=c1}
 if cav:qual.append((co,cav))
out=[row[:] for row in g]
# Inner cavity: color all zero cells except those deepest from boundary/object, kept 0
for co,cav in qual:
 d={p:min(abs(p[0]-r)+abs(p[1]-c) for r,c in co) for p in cav}; mx=max(d.values())
 for (r,c),v in d.items():
  if v<mx:out[r][c]=3
# Outer one-cell halo, 8-neighbor around qualifying objects
for co,cav in qual:
 for r,c in co:
  for a in range(max(0,r-1),min(R,r+2)):
   for b in range(max(0,c-1),min(C,c+2)):
    if g[a][b]==0 and (a,b) in ext:out[a][b]=2
assert len(out)==30 and all(len(row)==30 for row in out)
print('['+','.join('['+','.join(map(str,row))+']' for row in out)+']')

